def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    bands = []
    for r, row in enumerate(g):
        if w >= 3 and row[0] == row[-1] and row[0] != row[1] and all(x == row[1] for x in row[1:-1]):
            if bands and r == bands[-1][-1] + 1 and g[r-1][0] == row[0] and g[r-1][1] == row[1]:
                bands[-1].append(r)
            else:
                bands.append([r])

    if not bands:
        return g

    first_band = min(b[0] for b in bands)
    bg = g[0][0]
    seen = set()

    for r in range(first_band):
        for c in range(w):
            if g[r][c] == bg or (r, c) in seen:
                continue
            color = g[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < first_band and 0 <= nx < w and (ny, nx) not in seen and g[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            for band in bands:
                br = g[band[0]]
                if br[1] == color:
                    shift = band[-1] - max(y for y, x in cells)
                    for y, x in cells:
                        g[y + shift][x] = br[0]
                    break

    for r in range(first_band):
        for c in range(w):
            g[r][c] = bg
    return g
